package com.ems.model;
import java.math.BigDecimal; import java.time.LocalDate;
public class Employee { private long employeeId; private String fullName,email,phone,department,designation,employmentStatus,address; private BigDecimal salary; private LocalDate joiningDate,createdAt,updatedAt;
 public long getEmployeeId(){return employeeId;} public void setEmployeeId(long v){employeeId=v;} public String getFullName(){return fullName;} public void setFullName(String v){fullName=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} public String getDepartment(){return department;} public void setDepartment(String v){department=v;} public String getDesignation(){return designation;} public void setDesignation(String v){designation=v;} public BigDecimal getSalary(){return salary;} public void setSalary(BigDecimal v){salary=v;} public LocalDate getJoiningDate(){return joiningDate;} public void setJoiningDate(LocalDate v){joiningDate=v;} public String getEmploymentStatus(){return employmentStatus;} public void setEmploymentStatus(String v){employmentStatus=v;} public String getAddress(){return address;} public void setAddress(String v){address=v;} public LocalDate getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDate v){createdAt=v;} public LocalDate getUpdatedAt(){return updatedAt;} public void setUpdatedAt(LocalDate v){updatedAt=v;} }
